function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");
  noStroke();

  // Sky
  brush.fillBleed(0.45);
  brush.fillTexture(1.0, 100);
  brush.beginShape(0.5);
  vertex(200, 200);
  vertex(180, 180);
  vertex(200, 160);
  vertex(220, 180);
  vertex(200, 200);
  endShape(true);

  //ground
  brush.fillBleed(0.4);
  brush.fillTexture(0.8, 50);
  brush.beginShape(1.0);
  vertex(200, 380);
  vertex(200, 240);
  vertex(160, 240);
  vertex(160, 380);
  vertex(200, 380);
  endShape(true);

  //Hills
  brush.fillBleed(0.25);
  brush.fillTexture(0.5, 0);
  brush.beginShape(0.2);
  vertex(160, 240);
  vertex(180, 180);
  vertex(160, 160);
  vertex(180, 240);
  vertex(160, 240);
  endShape(true);
}

