function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");
  // Sky
  brush.fill("#87CEFA", 255);
  brush.beginShape(CURVATURE_15_15);
  brush.vertex(200, 0);
  brush.vertex(0, 200);
  brush.vertex(200, 300);
  brush.vertex(200, 400);
  brush.endShape(true);
  // Green hills
  brush.fill("#669900", 255);
  brush.beginShape(CURVATURE_15_15);
  brush.vertex(0, 0);
  brush.vertex(0, 120);
  brush.vertex(200, 140);
  brush.vertex(200, 400);
  brush.endShape(true);
  // Dusk
  brush.fill("#93706B", 255);
  brush.beginShape(CURVATURE_15_15);
  brush.vertex(0, 0);
  brush.vertex(0, 200);
  brush.vertex(0, 300);
  brush.vertex(0, 400);
  brush.endShape(true);
  // Water
  brush.fill("#0099FF", 255);
  brush.beginShape(CURVATURE_15_15);
  brush.vertex(400, 400);
  brush.vertex(200, 0);
  brush.vertex(400, 0);
  brush.endShape(true);
  // Paint back to front: sky first, then ground, then details
}

