  vertex(0, 400);
  vertex(200, 400);
  vertex(400, 400);
  vertex(400, 200);
  vertex(200, 200);
  vertex(0, 200);
  endShape(true);
  translate(200, 0);
  fillBleed(0.5);
  brush.beginShape(0.5);
  vertex(200, 400);
  vertex(400, 200);
