  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");
  brush.fill("#e64842", 100); // Orange/orange-red  
  brush.circle(0, 0, 40);
  brush.fill("#e85536", 100);
  brush.circle(0, 20, 20);
  brush.fill("#e64842", 100);
  brush.circle(0, 30, 20);
  brush.fill("#e08a72", 100);
  brush.circle(0, 30, 20);
  brush.fill("#e08a72", 100);
  brush.circle(0, 20, 20);
  brush.fill("#e64842", 100);
  brush.circle(0, 0, 40);

  brush.fill("#874234", 100);
  brush.beginShape(0.2);
  brush.vertex(0, 20);
  brush.vertex(40, 40);
  brush.vertex(0, 60);
  brush.vertex(-20, 40);
  brush.endShape(true);

  brush.fill("#c13446", 100);
  brush.beginShape(0.2);
