// Painting the scene
let max_red = 150, max_green = 150, max_blue = 230;
let pixel_red, pixel_green, pixel_blue;

draw = function () {
  background("#e08a72");
  paint();
};

paint = function() {
  // Draw the sky
  brush.fill(0, 0, 50); // sky blue
  brush.noFill();
  brush.stroke(0, 0, 150);
  brush.strokeWeight(5);

  strokeWeight(5);
  stroke(0, 0, 50); // stars
  brush.beginShape();
  for (let i = 0; i < 200; i++) {
    let radialGradient = ((i / 200) * 100) + 10;
    brush.vertex(150 + i * 1.5, 150 + i * 1.5 * 0.5);
    brush.vertex(150 + i * 0.5 - (i * 1.5) * 0.5, 150 + i * 0.5 + (i * 1.5) * 0.5);
    brush.vertex(150 + i * 1.5, 150 + i * 0.5);
  }
  brush.endShape(true);

  // Draw hills
  brush.stroke(200, 200, 200); // light green
  brush.strokeWeight(3);
  brush.beginShape();
  brush.vertex(100, 100);
  brush.vertex(0, 0);
  brush.vertex(0, 200);
  brush.vertex(100, 200);
  brush.endShape(true);

  // Draw the sun
  brush.fill(230, 150, 0);
  brush.stroke(130, 110, 20);
  brush.strokeWeight(5);
  brush.beginShape();
  brush.vertex(200, 200);
  brush.vertex(240, 180);
  brush.vertex(280, 220);
  brush.vertex(240, 260);
  brush.endShape(true);
};
