For watercolours:
- Look like a soft hue
- Don't make it shine too bright
- Use thin and wide strokes
- Express a view like an atelier rather than a painting technique

In structure:
- Implement a sun mask
- Implement a green hills brush (width = 12)
- Use shadow, mask, and speed on appropriate scale
- Use dragonfly stripes on very warm bright greens

Here's the solution:
```javascript
function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");
  stroke("#f9f7e2");
  const angle = 360 * getGlow / 4;
  for (let i = 0; i < 4; i++) {
    const r = cos(1 * i / 2 * pi) * 20;
    const g = cos(0.7 * i / 2 * pi) * 30;
    const b = cos(0.3 * i / 2 * pi) * 20;
    fill(b, g, r, 130);
    stroke("#b38c74");
    strokeWeight(60);
    const pattern = (angle + i) * 40;
    brush.fillPattern(pattern, "#b38c74");
    noStroke();
    const k = 0.5 * pattern;
    strokeWeight(1 + sin(3 * k / 4));
    circle(0, 0, r);
    fill("#013350");
    circle(0, 0, r / 10);
    fill("#000000");
    circle(0, 0, r / 16);
    fill("#b38c74");
    circle(0, 0, r / 120);
    fill("#5c5c5c");
    circle(0, 0, r / 24);
    fill(b, g, r, 200);
    circle(0, 0, r);
    noFill();
  }
}
